mapper.select:
SELECT external_id
FROM sessions
WHERE organization_uuid = #{organizationUUID}
AND workspace_uuid = #{workspaceUUID}
AND deleted_at IS NULL
AND metadata->>'evaluation_role' = 'agent_score'
AND metadata->>'experiment_id' = #{experimentID}
AND metadata->>'item_id' = #{itemID}
AND metadata->>'evaluator_version_id' = #{versionID}
LIMIT 1
